// PII-скрин: карта (+Луна) / IBAN / email / телефон / самопредставление по имени
// Решение из плана проекта — только regex, без LLM-проверки.
const text = $json.text || '';

function luhnCheck(numStr) {
  const digits = numStr.replace(/\D/g, '');
  if (digits.length < 13 || digits.length > 19) return false;
  let sum = 0, alt = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let n = parseInt(digits[i], 10);
    if (alt) { n *= 2; if (n > 9) n -= 9; }
    sum += n; alt = !alt;
  }
  return sum % 10 === 0;
}

const cardMatch = (text.match(/\b(?:\d[ -]?){13,19}\b/) || [])[0];
const hasCard = cardMatch ? luhnCheck(cardMatch) : false;
const hasIban = /\b[A-Z]{2}\d{2}[ ]?(?:\d{4}[ ]?){3,7}\d{1,4}\b/.test(text);
const hasEmail = /[\w.+-]+@[\w-]+\.[a-zA-Z]{2,}/.test(text);
const hasPhone = /\+?\d[\d\s()-]{7,}\d/.test(text);
const hasSelfName = /(меня зовут|я\s*[-—]\s*)\s+[А-ЯЁ][а-яё]+/i.test(text);

const sensitive = hasCard || hasIban || hasEmail || hasPhone || hasSelfName;
const types = [];
if (hasCard) types.push('card_number');
if (hasIban) types.push('iban');
if (hasEmail) types.push('email');
if (hasPhone) types.push('phone');
if (hasSelfName) types.push('self_name');

return { json: { ...$json, sensitive_detected: sensitive, sensitive_types: types } };

const staticData = $getWorkflowStaticData('global');
if (!staticData.messageCounts) staticData.messageCounts = {};

const chatId = $('Telegram Trigger').first().json.message.chat.id;
staticData.messageCounts[chatId] = (staticData.messageCounts[chatId] || 0) + 1;

const count = staticData.messageCounts[chatId];
const isReminderDue = count % 5 === 0; // каждое 5-е сообщение в этом чате

return [{ json: { ...$input.first().json, messageCount: count, isReminderDue } }];
